    gilded_bookspinecreaser = { name = "Pozlačen gubalec hrbtov knjig", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen gubalec hrbtov knjig za knjigoveze." },
